python3 "$LEGACY_BENCH_ROOT/test/executor_bench/run_latency.py" --candidate-only --include-legacy --candidate "$LEGACY_BENCH_ROOT/builddir_release/test/executor_bench/executor_latency_bench" --messages 2000 --warmup 32 --hops 8 --intervals 0 --spins 0,200 --repeats 3 --cpus 20-27 --producer-cpu 20 --consumer-cpus 24,25,26,27 --output /tmp/executor-legacy-profile/oversubscribed > /tmp/executor-legacy-oversubscribed.log 2>&1
